/** Everything the details panel shows for one node (UI-MAIN-35…43, G11). */
export interface TreeSummaryResult {
  /** Allocated bytes and files per file class, largest first */
  classes: ClassStat[];
  /** Newest modification time in the subtree (0 = unknown) */
  latest_mtime: number;
  node: NodeInfo;
  /** False inside the MFT pseudo folders ($NTFS 元数据, $孤立文件): no such path exists */
  on_disk: boolean;
  parent: NodeInfo | null;
  path: string;
  tag: "red" | "yellow" | "green" | "blue" | null;
  top_files: TopFile[];
  /** The volume of the scan root that holds the node */
  volume: VolumeInfo | null;
}

export interface UnsubscribeParams {
  sub: string;
}

export interface ViewFilterParams {
  cursor?: number | null;
  text: string;
  view_id: string;
}

/** ``view.frame``: a frame pushed without a request (scan progress, time-based filters). */
export interface ViewFrameEvent {
  frame: FrameInfo;
}

export interface ViewIdParams {
  view_id: string;
}

export interface ViewListParams {
  scan_id?: string | null;
}

export interface ViewListResult {
  views: ViewState[];
}

export interface ViewOpenParams {
  scan_id: string;
  settings?: ViewSettingsParams | null;
  viewport: Viewport;
}

export interface ViewResults {
  /** A filter is in effect (otherwise there are no rows) */
  active: boolean;
  alloc: number;
  /** Matching files below the zoom root (sum of the rows' counts) */
  files: number;
  /** Largest row, for the relative size bars */
  max_alloc: number;
  offset: number;
  rows: ResultRow[];
  /** Frame the rows were grouped by */
  seq: number;
  size: number;
  sort: "size" | "name" | "count";
  /** Number of rows */
  total: number;
  view_id: string;
}

export interface ViewResultsParams {
  limit?: number;
  offset?: number;
  /** New order (remembered per view); None keeps it */
  sort?: "size" | "name" | "count" | null;
  view_id: string;
}

export interface ViewRevealParams {
  /** A result row's key, or any node id */
  key: number;
  view_id: string;
}

export interface ViewSelectParams {
  key?: number | null;
  view_id: string;
}

export interface ViewSetParams {
  settings: ViewSettingsParams;
  view_id: string;
}

/** Fields left out keep their value. */
export interface ViewSettingsParams {
  color_mode?: "class" | "flat" | "time" | null;
  detail?: number | null;
  filter_mode?: "dim" | "hide" | null;
  /** CSS px */
  min_element?: number | null;
  show_free?: boolean | null;
  show_unknown?: boolean | null;
  sort_by_size?: boolean | null;
  viewport?: Viewport | null;
}

export interface ViewState {
  can_back: boolean;
  can_forward: boolean;
  can_up: boolean;
  color_mode: "class" | "flat" | "time";
  detail: number;
  filter_mode: "dim" | "hide";
  min_element: number;
  results_sort: "size" | "name" | "count";
  scan_id: string;
  selected: number | null;
  show_free: boolean;
  show_unknown: boolean;
  sort_by_size: boolean;
  view_id: string;
  viewport: Viewport;
  zoom_key: number;
  zoom_node: number;
}

export interface ViewTagParams {
  /** None clears the selection's tag and every tag below it (Ctrl+0) */
  color?: "red" | "yellow" | "green" | "blue" | null;
  view_id: string;
}

export interface ViewUpdate {
  changed: boolean;
  /** Current filter state (also without a frame) */
  filter: FilterInfo | null;
  /** Present when a new frame was sent */
  frame: FrameInfo | null;
  state: ViewState;
}

export interface ViewZoomParams {
  /** A block's key from the last frame, or a node id */
  key: number;
  view_id: string;
}

export interface Viewport {
  dpr?: number;
  /** CSS px */
  height: number;
  /** CSS px */
  width: number;
}

export interface VolumeInfo {
  cluster_size: number;
  device: string;
  free: number;
  fs_type: string;
  is_remote: boolean;
  is_removable: boolean;
  /** The system volume (selected by default on the start page) */
  is_system: boolean;
  label: string;
  /** Storage media (start page cards, IO tuning in M4) */
  media: "nvme_ssd" | "sata_ssd" | "ssd" | "hdd" | "usb_hdd" | "usb_ssd" | "usb_flash" | "sd_card" | "network" | "virtual" | "unknown";
  mount_point: string;
  /** Why the volume cannot be scanned now ('' = available) */
  reason: string;
  /** Network volumes: the server path (\\server\share, host:/export) */
  remote_path: string;
  serial: string;
  total: number;
  used: number;
}

export interface VolumeListResult {
  /** An MFT scan needs no administrator prompt now (the backend has administrator rights, or the read-only helper is running) */
  elevated: boolean;
  volumes: VolumeInfo[];
}

export interface Methods {
  /** Subscribe to an event topic. */
  "$/subscribe": { params: SubscribeParams; result: SubscribeResult };
  /** Cancel a subscription. */
  "$/unsubscribe": { params: UnsubscribeParams; result: EmptyResult };
  /** Ask the backend to shut down gracefully. */
  "app.shutdown": { params: Empty; result: ShutdownResult };
  /** Parse a filter: tokens, diagnostics, pending condition, completion and normal form. */
  "filter.parse": { params: FilterParseParams; result: FilterParse };
  /** File classes and platform limits for the filter. */
  "filter.vocab": { params: Empty; result: FilterVocab };
  /** Load state of every local disk, with history. */
  "io.status": { params: Empty; result: IoStatusList };
  /** Clear the recents of a scan target and the shared filters. */
  "palette.clear": { params: PaletteClearParams; result: EmptyResult };
  /** All commands with names, icons and default keys. */
  "palette.commands": { params: Empty; result: PaletteCommandList };
  /** Path group: name search, folder listing or selection seed. */
  "palette.paths": { params: PalettePathsParams; result: PalettePaths };
  /** Matches of a filter expression on a whole scan. */
  "palette.preview": { params: PalettePreviewParams; result: PalettePreview };
  /** Commands, recents and direct items for the palette input. */
  "palette.query": { params: PaletteQueryParams; result: PaletteResult };
  /** Record a path jump or filter run from the palette. */
  "palette.remember": { params: PaletteRememberParams; result: EmptyResult };
  /** Stop a running scan (partial tree stays). */
  "scan.cancel": { params: ScanIdParams; result: ScanStatus };
  /** Validate typed paths and merge nested ones (UI-W1-25). */
  "scan.check_paths": { params: PathCheckParams; result: PathCheckResult };
  /** Forget a scan and free its memory. */
  "scan.close": { params: ScanIdParams; result: EmptyResult };
  /** Scans held by the backend. */
  "scan.list": { params: Empty; result: ScanListResult };
  /** Stop dispatching reads; batches in flight finish (W2). */
  "scan.pause": { params: ScanIdParams; result: ScanStatus };
  /** Continue a paused scan where it stopped. */
  "scan.resume": { params: ScanIdParams; result: ScanStatus };
  /** Change the disk load limit of a running scan (W2). */
  "scan.set_load": { params: ScanSetLoadParams; result: ScanStatus };
  /** Start scanning one or more roots. */
  "scan.start": { params: ScanStartParams; result: ScanStatus };
  /** Current status of a scan. */
  "scan.status": { params: ScanIdParams; result: ScanStatus };
  /** Switch a running hard scan to the MFT fast scan (asks for administrator rights; the hard scan goes on until the helper is ready, and on if it cannot start). */
  "scan.use_mft": { params: ScanIdParams; result: ScanStatus };
  /** Authenticate and negotiate protocol/capabilities. */
  "session.hello": { params: HelloParams; result: HelloResult };
  /** All settings with their metadata (W7). */
  "settings.get": { params: Empty; result: SettingsState };
  /** Restore the defaults of one page, or of everything. */
  "settings.reset": { params: SettingsResetParams; result: SettingsState };
  /** Change some settings (validated, saved atomically). */
  "settings.update": { params: SettingsUpdateParams; result: SettingsState };
  /** Auto-saved snapshots, newest first (W1). */
  "snapshot.list": { params: Empty; result: SnapshotListResult };
  /** Open a snapshot as a finished scan. */
  "snapshot.load": { params: SnapshotLoadParams; result: ScanStatus };
  /** Save a scan as a snapshot file. */
  "snapshot.save": { params: SnapshotSaveParams; result: SnapshotInfo };
  /** Server, platform and session information. */
  "system.info": { params: Empty; result: SystemInfo };
  /** Round-trip check; echoes the payload. */
  "system.ping": { params: PingParams; result: PingResult };
  /** A page of a node's children. */
  "tree.children": { params: TreeChildrenParams; result: TreeChildrenResult };
  /** Look up a node by absolute path. */
  "tree.find": { params: TreeFindParams; result: TreeFindResult };
  /** One node with its full path. */
  "tree.node": { params: TreeNodeParams; result: TreeNodeResult };
  /** Details-panel data of a node: parent, largest files, per-class totals, newest change, tag, volume. */
  "tree.summary": { params: TreeSummaryParams; result: TreeSummaryResult };
  /** Back to the previous zoom root. */
  "view.back": { params: ViewIdParams; result: ViewUpdate };
  /** Close a view. */
  "view.close": { params: ViewIdParams; result: EmptyResult };
  /** Set the view's filter expression. */
  "view.filter": { params: ViewFilterParams; result: ViewUpdate };
  /** Forward again. */
  "view.forward": { params: ViewIdParams; result: ViewUpdate };
  /** Back to the whole scan / volume. */
  "view.home": { params: ViewIdParams; result: ViewUpdate };
  /** Views of this session (optionally of one scan). */
  "view.list": { params: ViewListParams; result: ViewListResult };
  /** Open a view (tab / pane) on a scan; sends its first frame. */
  "view.open": { params: ViewOpenParams; result: ViewUpdate };
  /** Send a fresh frame of a view. */
  "view.render": { params: ViewIdParams; result: ViewUpdate };
  /** A page of the filter result list, grouped by visible block. */
  "view.results": { params: ViewResultsParams; result: ViewResults };
  /** Select a block and navigate until it is drawn (W3 click). */
  "view.reveal": { params: ViewRevealParams; result: ViewUpdate };
  /** Select a block (or clear the selection). */
  "view.select": { params: ViewSelectParams; result: ViewUpdate };
  /** Change detail, viewport, switches, colour or filter mode. */
  "view.set": { params: ViewSetParams; result: ViewUpdate };
  /** Tag the selection (Ctrl+1..4) or clear tags (Ctrl+0). */
  "view.tag": { params: ViewTagParams; result: ViewUpdate };
  /** Zoom to the parent; the folder left is selected. */
  "view.up": { params: ViewIdParams; result: ViewUpdate };
  /** Zoom into a block (double-click / Enter). */
  "view.zoom": { params: ViewZoomParams; result: ViewUpdate };
  /** Volumes offered on the start page (W1). */
  "volume.list": { params: Empty; result: VolumeListResult };
}

export type MethodName = keyof Methods;

export interface Events {
  /** Progress of a long-running request. */
  "$/progress": ProgressEvent;
  /** Load state of a disk for an 'io' subscription (2 Hz). */
  "io.load": IoStatusEvent;
  /** A backend log record for a 'log' subscription. */
  "log.record": LogRecordEvent;
  /** Status of a scan for a 'scan' subscription. */
  "scan.progress": ScanProgressEvent;
  /** Settings changed (any client, or the file was edited). */
  "settings.changed": SettingsChangedEvent;
  /** A frame pushed without a request (scan progress, time). */
  "view.frame": ViewFrameEvent;
}

export type EventName = keyof Events;
